   206	/// Resolves the escapes of a quoted value as the tokenizer hands it out. Borrows when there is nothing to resolve.
   207	pub fn unescape(raw: &str) -> Cow<'_, str> {
   208	    if !raw.contains('\\') {
   209	        return Cow::Borrowed(raw);
   210	    }
   211	    let mut text = String::with_capacity(raw.len());
   212	    let mut chars = raw.chars();
   213	    while let Some(c) = chars.next() {
   214	        if c != '\\' {
   215	            text.push(c);
   216	            continue;
   217	        }
   218	        match chars.next() {
   219	            Some('n') => text.push('\n'),
   220	            Some('t') => text.push('\t'),
   221	            Some(other) => text.push(other),
   222	            None => text.push('\\'),
   223	        }
   224	    }
   225	    Cow::Owned(text)
   226	}
